45	export class SmartRouter {
46	    static route(query: string, options: RoutingRequestOptions = {}): RoutingDecision {
47	        const normalizedQuery = (query || '').trim();
48	        const queryLower = normalizedQuery.toLowerCase();
49	
50	        const intent = options.intent || this.detectIntent(queryLower);
51	        const complexity = this.detectComplexity(normalizedQuery, queryLower, intent);
52	        const risk = this.detectRisk(queryLower, intent);
53	        const providerStatus = options.providerStatus;
54	        const preferredRuntime = this.detectRuntime(intent, complexity, risk, options, providerStatus);
55	        const reasoningBudget = options.reasoningBudget || complexity;
56	        const retrievalProfile = options.retrievalProfile || this.detectRetrievalProfile(queryLower, intent);
57	        const compressionMode = this.detectCompressionMode(options.compressionMode, preferredRuntime, risk);
58	        const preferredModel = options.modelId || this.detectPreferredModel(intent, preferredRuntime, complexity, providerStatus);
59	        const fallbackChain = this.buildFallbackChain(preferredModel, intent, preferredRuntime, complexity, options, providerStatus);
60	
61	        console.log(
62	            `⬡ SMART_ROUTER :: intent=${intent} complexity=${complexity} risk=${risk} runtime=${preferredRuntime} model=${preferredModel}`
63	        );
64	
65	        return {
66	            intent,
67	            complexity,
68	            risk,
69	            preferredRuntime,
70	            preferredModel,
71	            fallbackChain,
72	            compressionMode,
73	            reasoningBudget,
74	            retrievalProfile
75	        };
76	    }
