78	    private static detectIntent(queryLower: string): NeuralTaskIntent {
79	        if (queryLower.startsWith('btw') || queryLower.startsWith('/btw')) {
80	            return 'orchestration';
81	        }
82	
83	        if (this.hasAny(queryLower, ['review', 'audit', 'vulnerability', 'security', 'bug risk', 'regression'])) {
84	            return 'review';
85	        }
86	
87	        if (this.hasAny(queryLower, [
88	            'architect', 'architecture', 'roadmap', 'strategy', 'plan', 'design', 'blueprint', 'tradeoff'
89	        ])) {
90	            return 'strategy';
91	        }
92	
93	        if (this.hasAny(queryLower, [
94	            'btw', 'offload', 'delegate', 'handoff',
95	            'swarm', 'orchestrate', 'orchestration', 'multi-agent', 'conclave', 'decompose', 'coordinate',
96	            'openmythos', 'mythos', 'claude-code-unpacked', 'claudeunpacked', 'frontend-design', 'frontenddesign', 'antigravity'
97	        ])) {
98	            return 'orchestration';
99	        }
100	
101	        const retrievalSignals = ['find', 'lookup', 'search', 'where is', 'show me', 'status', 'ticket', 'briefing', 'client', 'note'];
102	        const businessSignals = ['ic2m', 'c2moviez', 'claudio', 'plane', 'outlook', 'meeting', 'project'];
103	        const codeSignals = ['refactor', 'implement', 'fix', 'debug', 'typescript', 'javascript', 'function', 'class', 'test', 'code', 'patch'];
104	
105	        if ((this.hasAny(queryLower, retrievalSignals) || this.hasAny(queryLower, businessSignals)) && !this.hasAny(queryLower, codeSignals)) {
106	            return 'retrieval';
107	        }
108	
109	        if (this.hasAny(queryLower, [
110	            'refactor', 'implement', 'fix', 'debug', 'typescript', 'javascript', 'function', 'class', 'test',
111	            'compile', 'build error', 'code', 'patch'
112	        ])) {
113	            return 'coding';
114	        }
115	
116	        if (this.hasAny(queryLower, retrievalSignals)) {
117	            return 'retrieval';
118	        }
119	
120	        return 'ops';
121	    }
