123	    private static detectComplexity(query: string, queryLower: string, intent: NeuralTaskIntent): QueryComplexity {
124	        const longInput = query.length > 1400;
125	        const mediumInput = query.length > 450;
126	
127	        if (
128	            longInput ||
129	            this.hasAny(queryLower, [
130	                'security', 'architecture', 'ambiguous', 'tradeoff', 'migration', 'council', 'multi-step', 'deep analysis'
131	            ]) ||
132	            intent === 'strategy'
133	        ) {
134	            return 'deep';
135	        }
136	
137	        if (
138	            mediumInput ||
139	            intent === 'coding' ||
140	            intent === 'review' ||
141	            intent === 'orchestration'
142	        ) {
143	            return 'balanced';
144	        }
145	
146	        return 'cheap';
147	    }
