149	    private static detectRisk(queryLower: string, intent: NeuralTaskIntent): QueryRisk {
150	        if (
151	            intent === 'review' ||
152	            this.hasAny(queryLower, [
153	                'security', 'billing', 'database', 'migration', 'production', 'auth', 'credential', 'permission'
154	            ])
155	        ) {
156	            return 'high';
157	        }
158	
159	        if (intent === 'coding' || intent === 'strategy' || intent === 'orchestration') {
160	            return 'medium';
161	        }
162	
163	        return 'low';
164	    }
