166	    private static detectRuntime(
167	        intent: NeuralTaskIntent,
168	        complexity: QueryComplexity,
169	        risk: QueryRisk,
170	        options: RoutingRequestOptions,
171	        providerStatus?: RoutingRequestOptions['providerStatus']
172	    ): PreferredRuntime {
173	        if (options.allowLocal === false && options.allowCloud === false) {
174	            return 'local';
175	        }
176	
177	        if (options.allowLocal === false) return 'cloud';
178	        if (options.allowCloud === false) return 'local';
179	
180	        // Check provider health if available
181	        const localOnline = !providerStatus || providerStatus.local;
182	        const cloudOnline = !providerStatus || providerStatus.cloud || providerStatus.anthropic || providerStatus.google || providerStatus.openai || providerStatus.moonshot || providerStatus.kimi;
183	
184	        if (!localOnline && cloudOnline) return 'cloud';
185	        if (localOnline && !cloudOnline) return 'local';
186	
187	        // PRIORITIZE_LOCAL_FIRST
188	        if (intent === 'ops' || intent === 'retrieval') return 'local';
189	        if (complexity === 'cheap' || complexity === 'balanced') return 'local';
190	        
191	        // High risk or deep strategy still benefit from hybrid/cloud fallback
192	        if (risk === 'high' && complexity === 'deep') return 'hybrid';
193	        if (intent === 'review' && complexity === 'deep') return 'hybrid';
194	        
195	        return 'local';
196	    }
